import{_ as a,o as t,c as i,a8 as r}from"./chunks/framework.CNIpabDg.js";const g=JSON.parse('{"title":"Manage browser disks","description":"Create, switch, or deliberately remove browser-hosted Xila disks.","frontmatter":{"layout":"doc","docType":"how-to","description":"Create, switch, or deliberately remove browser-hosted Xila disks."},"headers":[],"relativePath":"how-to/reset-browser-storage.md","filePath":"how-to/reset-browser-storage.md","lastUpdated":1792240122000}'),o={name:"how-to/reset-browser-storage.md"};function s(n,e,l,d,h,c){return t(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792240122000"},[...e[0]||(e[0]=[r('<h1 id="manage-browser-disks" tabindex="-1">Manage browser disks <a class="header-anchor" href="#manage-browser-disks" aria-label="Permalink to &quot;Manage browser disks&quot;">​</a></h1><p>Use the browser example&#39;s Help panel to create another Xila disk, switch between saved disks, or permanently remove an unused image.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Removing a disk erases its data</p><p>Deleting an image permanently removes the files, configuration, and credentials stored on that disk. Copy anything you need before removing it. Clearing all site data is broader and can remove every Xila image and other storage belonging to the same origin.</p></div><p>Browser disks are origin-specific. The legacy/default image is <code>xila_drive.img</code>; new images use date-based names such as <code>xila_2026-10-17.img</code> and receive a numeric suffix when necessary.</p><h2 id="create-a-fresh-disk" tabindex="-1">Create a fresh disk <a class="header-anchor" href="#create-a-fresh-disk" aria-label="Permalink to &quot;Create a fresh disk&quot;">​</a></h2><ol><li>Open the <strong>Xila Help</strong> panel beside the browser demonstration.</li><li>Select <strong>New disk</strong>.</li><li>Confirm the switch when prompted.</li><li>Xila saves the current image, releases its Web Lock, and reloads on the new image.</li></ol><p>A fresh disk boots with the <strong>administrator</strong> account and an empty password. The bundled Calculator, Clock, and Pixel Painter applications are installed during startup.</p><h2 id="switch-to-another-saved-disk" tabindex="-1">Switch to another saved disk <a class="header-anchor" href="#switch-to-another-saved-disk" aria-label="Permalink to &quot;Switch to another saved disk&quot;">​</a></h2><ol><li>In <strong>Available disks</strong>, select the target image.</li><li>Choose <strong>Use selected disk</strong>.</li><li>Confirm the restart.</li></ol><p>The current disk stops accepting new writes while Xila commits pending changes. After the lock is released, the page reloads using the selected image. The selection is remembered for this browser origin.</p><p>Only one Xila tab can hold a given disk&#39;s Web Lock at a time. Different tabs may use different disks.</p><h2 id="remove-an-unused-disk" tabindex="-1">Remove an unused disk <a class="header-anchor" href="#remove-an-unused-disk" aria-label="Permalink to &quot;Remove an unused disk&quot;">​</a></h2><ol><li>Select a disk that is not active in the current tab.</li><li>Choose <strong>Remove</strong>.</li><li>Confirm the permanent deletion.</li></ol><p>The browser refuses removal when another Xila tab currently owns that disk. Close the tab using it, then retry. The active disk is not offered for removal from its own tab.</p><h2 id="clear-the-whole-origin" tabindex="-1">Clear the whole origin <a class="header-anchor" href="#clear-the-whole-origin" aria-label="Permalink to &quot;Clear the whole origin&quot;">​</a></h2><p>Use the browser&#39;s site-data settings only when you deliberately want to remove all storage for the demonstration&#39;s origin. This is broader than removing one disk from the Help panel.</p><h2 id="verify-completion" tabindex="-1">Verify completion <a class="header-anchor" href="#verify-completion" aria-label="Permalink to &quot;Verify completion&quot;">​</a></h2><p>After switching or creating a disk, confirm that the expected files and account are visible. A newly created image should contain the default administrator and bundled applications; an existing image should preserve its own users, files, and configuration.</p><p>An invalid existing image or a mount error does not trigger an automatic reset. Xila preserves the image and stops with an error instead of formatting it.</p><h2 id="related-documentation" tabindex="-1">Related documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related documentation&quot;">​</a></h2><ul><li><a href="/explanation/browser-storage.html">Browser storage</a> for cache, autosave, locking, and durability behavior.</li><li><a href="/reference/wasm-runtime.html#browser-capabilities">Browser capabilities</a>.</li></ul>',22)])])}const u=a(o,[["render",s]]);export{g as __pageData,u as default};
